using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(int count = 1) =>
        Enumerable.Range(1, count).Select(i => new OrderItem
        {
            ProductName = $"Product {i}",
            Price = 10.00m * i,
            Quantity = i
        }).ToList();

    [TestMethod]
    public void CreateOrder_WithValidInput_ReturnsOrderWithCorrectProperties()
    {
        // Arrange
        var customerId = "customer-1";
        var items = CreateItems(2);

        // Act
        var order = _sut.CreateOrder(customerId, items);

        // Assert
        Assert.IsNotNull(order);
        Assert.AreEqual(customerId, order.CustomerId);
        Assert.AreEqual(2, order.Items.Count);
        Assert.IsNotNull(order.Id);
    }

    [TestMethod]
    public void CreateOrder_WithMultipleItems_CalculatesTotalCorrectly()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "A", Price = 5.00m, Quantity = 2 },
            new() { ProductName = "B", Price = 3.00m, Quantity = 4 },
        };

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert — (5*2) + (3*4) = 22
        Assert.AreEqual(22.00m, order.Total);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder(null!, CreateItems()));

        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder("cust-1", null!));

        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("cust-1", []));

        Assert.AreEqual("Cannot create an order with no items.", ex.Message);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var before = DateTime.UtcNow;

        // Act
        var order = _sut.CreateOrder("cust-1", CreateItems());

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
    }

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsOrder()
    {
        // Arrange
        var created = _sut.CreateOrder("cust-1", CreateItems());

        // Act
        var found = _sut.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, found);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        var result = _sut.GetOrder("non-existent-id");

        Assert.IsNull(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithMatchingOrders_ReturnsAllCustomerOrders()
    {
        // Arrange
        _sut.CreateOrder("cust-A", CreateItems());
        _sut.CreateOrder("cust-A", CreateItems(2));
        _sut.CreateOrder("cust-B", CreateItems());

        // Act
        var orders = _sut.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoMatchingOrders_ReturnsEmptyList()
    {
        _sut.CreateOrder("cust-A", CreateItems());

        var orders = _sut.GetOrdersByCustomer("cust-Z");

        Assert.IsEmpty(orders);
    }
}

using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _sut;

    public PriceCalculatorTests()
    {
        _sut = new PriceCalculator();
    }

    [TestMethod]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "10% tax")]
    [DataRow(5.00, 3, 0.0, 15.00, DisplayName = "No tax")]
    [DataRow(100.00, 1, 0.25, 125.00, DisplayName = "25% tax")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _sut.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    public void CalculateTotal_WithNegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, -1, 0.1m));

        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_WithNegativeUnitPrice_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(-5m, 1, 0.1m));

        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Below zero")]
    [DataRow(1.01, DisplayName = "Above one")]
    public void CalculateTotal_WithInvalidTaxRate_ThrowsArgumentOutOfRangeException(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, 1, (decimal)taxRate));

        Assert.AreEqual("taxRate", ex.ParamName);
    }

    [TestMethod]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(200.00, 50.0, 100.00, DisplayName = "50% off")]
    [DataRow(75.00, 0.0, 75.00, DisplayName = "No discount")]
    [DataRow(50.00, 100.0, 0.00, DisplayName = "100% off")]
    public void ApplyDiscount_WithValidPercent_ReturnsDiscountedPrice(
        double price, double discountPercent, double expected)
    {
        var result = _sut.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(101.0, DisplayName = "Over 100% discount")]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRangeException(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.ApplyDiscount(100m, (decimal)discountPercent));
    }

    [TestMethod]
    public void FormatPrice_WithDefaultSymbol_ReturnsDollarFormat()
    {
        var result = _sut.FormatPrice(19.99m);

        Assert.AreEqual("$19.99", result);
    }

    [TestMethod]
    [DataRow("€", 25.50, "€25.50", DisplayName = "Euro")]
    [DataRow("£", 9.00, "£9.00", DisplayName = "Pound")]
    public void FormatPrice_WithCustomSymbol_ReturnsFormattedPrice(
        string symbol, double price, string expected)
    {
        var result = _sut.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

